package edu.swiftattend;

import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import javax.crypto.Mac;
import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.time.*;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

@RestController @RequestMapping("/api/attendance")
public class AttendanceController {
    private final JdbcTemplate db; private final ObjectMapper json=new ObjectMapper(); private final SecureRandom random=new SecureRandom(); private final SecurityEventService securityEvents;
    @org.springframework.beans.factory.annotation.Value("${app.qr.max-age-ms}") long maxAge;
    @org.springframework.beans.factory.annotation.Value("${app.qr.future-skew-ms}") long futureSkew;
    AttendanceController(JdbcTemplate db,SecurityEventService securityEvents){this.db=db;this.securityEvents=securityEvents;}
    record Start(@NotBlank @Size(max=15) String subjectCode,@NotBlank @Size(max=120) String subjectName,@NotBlank @Size(max=50) String roomNumber,@NotBlank @Size(max=60) String batch, @DecimalMin("-90") @DecimalMax("90") Double latitude,@DecimalMin("-180") @DecimalMax("180") Double longitude,@DecimalMin("10") @DecimalMax("1000") Double radiusMeters,String scheduleId){}
    record Verify(@NotBlank String sessionId,@Positive long timestamp,@NotBlank String nonce,@NotBlank String signature,@NotNull List<Double> faceDescriptor,@NotNull Boolean livenessPassed,@NotBlank String livenessChallenge,@DecimalMin("-90") @DecimalMax("90") double latitude,@DecimalMin("-180") @DecimalMax("180") double longitude){}
    record QrImage(@NotBlank String sessionId,@Positive long timestamp,@NotBlank @Size(max=40) String nonce,@NotBlank @Pattern(regexp="[0-9a-fA-F]{64}") String signature){}
    record Override(@NotBlank String sessionId,@NotBlank String studentId,@NotBlank @Pattern(regexp="PRESENT|LATE|EXCUSED|ABSENT") String status,@NotBlank @Size(max=300) String reason,@Size(max=1000) String notes){}
    enum TimestampResult { VALID, EXPIRED, FUTURE }

    @PostMapping("/session/start") @PreAuthorize("hasRole('TEACHER')") @Transactional
    Map<String,Object> start(@AuthenticationPrincipal String who,@Valid @RequestBody Start r){
        UUID teacher=UUID.fromString(who), id=UUID.randomUUID();
        if(r.latitude()==null||r.longitude()==null) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Allow classroom location to anchor the attendance geofence.");
        db.update("UPDATE attendance_session SET status='ENDED',ended_at=now() WHERE teacher_id=? AND status='ACTIVE'",teacher);
        UUID subject=db.query("SELECT id FROM subject WHERE teacher_id=? AND code=?",rs->rs.next()?rs.getObject(1,UUID.class):null,teacher,r.subjectCode().trim().toUpperCase());
        if(subject==null){subject=UUID.randomUUID();db.update("INSERT INTO subject(id,teacher_id,code,name) VALUES(?,?,?,?)",subject,teacher,r.subjectCode().trim().toUpperCase(),r.subjectName().trim());}
        UUID schedule=null;if(r.scheduleId()!=null&&!r.scheduleId().isBlank()){schedule=uuid(r.scheduleId());if(db.queryForObject("SELECT count(*) FROM class_schedule WHERE id=? AND teacher_id=? AND subject_id=?",Integer.class,schedule,teacher,subject)==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Schedule does not match this teacher and subject.");}
        byte[] secret=new byte[32];random.nextBytes(secret);
        db.update("INSERT INTO attendance_session(id,teacher_id,subject_id,subject_code,subject_name,room_number,batch,schedule_id,secret_key,status,latitude,longitude,geofence_radius_meters) VALUES(?,?,?,?,?,?,?,?,?,'ACTIVE',?,?,?)",id,teacher,subject,r.subjectCode().trim().toUpperCase(),r.subjectName().trim(),r.roomNumber().trim(),r.batch().trim(),schedule,secret,r.latitude(),r.longitude(),r.radiusMeters()==null?100:r.radiusMeters());
        return Map.of("success",true,"sessionId",id,"subjectCode",r.subjectCode().trim().toUpperCase(),"subjectName",r.subjectName(),"roomNumber",r.roomNumber(),"batch",r.batch(),"startedAt",Instant.now());
    }
    @PostMapping("/session/end") @PreAuthorize("hasRole('TEACHER')")
    Map<String,Object> end(@AuthenticationPrincipal String who,@RequestBody Map<String,String> body){UUID id=uuid(body.get("sessionId"));int n=db.update("UPDATE attendance_session SET status='ENDED',ended_at=now() WHERE id=? AND teacher_id=? AND status='ACTIVE'",id,UUID.fromString(who));if(n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Active session not found.");SessionSocketHandler.broadcast(id,Map.of("type","session_ended","sessionId",id,"endedAt",Instant.now()));return Map.of("success",true,"sessionId",id,"endedAt",Instant.now());}
    @GetMapping("/session/active") Map<String,Object> active(@AuthenticationPrincipal String who,org.springframework.security.core.Authentication auth){
        String role=auth.getAuthorities().iterator().next().getAuthority().replace("ROLE_","");
        return db.query("SELECT id,teacher_id,subject_code,subject_name,room_number,batch,status,started_at,total_attended FROM attendance_session WHERE status='ACTIVE' AND ((?='TEACHER' AND teacher_id=CAST(? AS UUID)) OR (?='STUDENT' AND lower(trim(batch))=(SELECT lower(trim(batch)) FROM app_user WHERE id=CAST(? AS UUID) AND role='STUDENT' AND batch IS NOT NULL))) ORDER BY started_at DESC LIMIT 1",rs->rs.next()?Map.of("success",true,"sessionId",rs.getObject("id"),"teacherId",rs.getObject("teacher_id"),"subjectCode",rs.getString("subject_code"),"subjectName",rs.getString("subject_name"),"roomNumber",rs.getString("room_number"),"batch",rs.getString("batch"),"status",rs.getString("status"),"startedAt",rs.getTimestamp("started_at").toInstant(),"totalAttended",rs.getInt("total_attended")):Map.of("success",true,"session",Map.of()),role,who,role,who);
    }
    @GetMapping("/session/{id}/qr") @PreAuthorize("hasRole('TEACHER')") Map<String,Object> qr(@AuthenticationPrincipal String who,@PathVariable String id){return qrForTeacher(UUID.fromString(who),uuid(id));}
    @GetMapping(value="/session/{id}/qr.png",produces="image/png") @PreAuthorize("hasRole('TEACHER')") byte[] qrImage(@AuthenticationPrincipal String who,@PathVariable String id){return encodeQr(qrForTeacher(UUID.fromString(who),uuid(id)));}
    @PostMapping(value="/session/{id}/qr.png",produces="image/png") @PreAuthorize("hasRole('TEACHER')") byte[] encodeHeartbeat(@AuthenticationPrincipal String who,@PathVariable String id,@Valid @RequestBody QrImage payload){UUID session=uuid(id);if(!session.toString().equalsIgnoreCase(payload.sessionId()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"QR payload belongs to another session.");Object[] key=db.query("SELECT secret_key FROM attendance_session WHERE id=? AND teacher_id=? AND status='ACTIVE'",rs->rs.next()?new Object[]{rs.getBytes(1)}:null,session,UUID.fromString(who));if(key==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Session ended or unavailable.");TimestampResult age=timestampStatus(payload.timestamp(),System.currentTimeMillis(),maxAge,futureSkew);if(age!=TimestampResult.VALID)throw new ResponseStatusException(age==TimestampResult.EXPIRED?HttpStatus.GONE:HttpStatus.BAD_REQUEST,"QR payload is outside the valid time window.");String signature=sign((byte[])key[0],session+":"+payload.timestamp()+":"+payload.nonce());if(!MessageDigest.isEqual(signature.getBytes(StandardCharsets.US_ASCII),payload.signature().toLowerCase().getBytes(StandardCharsets.US_ASCII)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"QR signature is invalid.");return encodeQr(Map.of("sessionId",session,"timestamp",payload.timestamp(),"nonce",payload.nonce(),"signature",signature,"validityMs",maxAge));}
    private byte[] encodeQr(Map<String,Object> payload){try{var matrix=new com.google.zxing.qrcode.QRCodeWriter().encode(json.writeValueAsString(payload),com.google.zxing.BarcodeFormat.QR_CODE,320,320);var out=new java.io.ByteArrayOutputStream();com.google.zxing.client.j2se.MatrixToImageWriter.writeToStream(matrix,"PNG",out);return out.toByteArray();}catch(Exception e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"QR generation failed.");}}
    Map<String,Object> qrForTeacher(UUID teacher,UUID session){return db.query("SELECT secret_key FROM attendance_session WHERE id=? AND teacher_id=? AND status='ACTIVE'",rs->{if(!rs.next())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Session ended or unavailable.");return makeQr(session,rs.getBytes(1));},session,teacher);}
    Map<String,Object> publicQr(UUID session){return db.query("SELECT secret_key FROM attendance_session WHERE id=? AND status='ACTIVE'",rs->{if(!rs.next())return null;return makeQr(session,rs.getBytes(1));},session);}
    private Map<String,Object> makeQr(UUID session,byte[] secret){long ts=System.currentTimeMillis();byte[] n=new byte[12];random.nextBytes(n);String nonce=HexFormat.of().formatHex(n).toUpperCase();String sig=sign(secret,session+":"+ts+":"+nonce);return Map.of("sessionId",session,"timestamp",ts,"nonce",nonce,"signature",sig,"validityMs",maxAge);}

    @PostMapping("/verify-qr") @PreAuthorize("hasRole('STUDENT')") @Transactional
    Map<String,Object> verify(@AuthenticationPrincipal String who,@Valid @RequestBody Verify v,jakarta.servlet.http.HttpServletRequest req){
        long started=System.nanoTime();UUID student=UUID.fromString(who),session=uuid(v.sessionId());TimestampResult timestampResult=timestampStatus(v.timestamp(),System.currentTimeMillis(),maxAge,futureSkew);
        if(timestampResult==TimestampResult.FUTURE){logEvent(student,session,"FUTURE_QR_TIMESTAMP","QR timestamp ahead of server",req);throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"QR timestamp is ahead of server time.");}
        if(timestampResult==TimestampResult.EXPIRED){logEvent(student,session,"EXPIRED_QR","QR older than allowed window",req);throw new ResponseStatusException(HttpStatus.GONE,"QR expired. Scan the current code.");}
        if(v.signature().length()!=64||!v.signature().matches("[0-9a-fA-F]{64}")){logEvent(student,session,"MALFORMED_QR_SIGNATURE","Malformed QR signature",req);throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid QR signature.");}
        Object[] s=db.query("SELECT s.secret_key,s.subject_id,s.subject_code,s.subject_name,s.status,s.latitude,s.longitude,s.geofence_radius_meters,u.name,u.enrollment_number,u.department,u.face_descriptor FROM attendance_session s JOIN app_user u ON u.id=? AND u.role='STUDENT' AND lower(trim(u.batch))=lower(trim(s.batch)) WHERE s.id=?",rs->rs.next()?new Object[]{rs.getBytes(1),rs.getObject(2,UUID.class),rs.getString(3),rs.getString(4),rs.getString(5),rs.getObject(6,Double.class),rs.getObject(7,Double.class),rs.getDouble(8),rs.getString(9),rs.getString(10),rs.getString(11),rs.getString(12)}:null,student,session);
        if(s==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Session is unavailable.");if(!"ACTIVE".equals(s[4])){logEvent(student,session,"INACTIVE_SESSION","QR submitted for ended session",req);throw new ResponseStatusException(HttpStatus.GONE,"Attendance session has ended.");}
        String expected=sign((byte[])s[0],session+":"+v.timestamp()+":"+v.nonce());if(!MessageDigest.isEqual(expected.toLowerCase().getBytes(StandardCharsets.US_ASCII),v.signature().toLowerCase().getBytes(StandardCharsets.US_ASCII))){logEvent(student,session,"INVALID_QR_SIGNATURE","HMAC signature did not match",req);throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"QR signature is invalid.");}
        if(!Boolean.TRUE.equals(v.livenessPassed())||!Set.of("BLINK_TWICE","TURN_HEAD_LEFT","TURN_HEAD_RIGHT","SMILE").contains(v.livenessChallenge())){logEvent(student,session,"LIVENESS_REJECTED","Camera challenge missing or not completed",req);throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Complete the live camera challenge before attendance.");}
        if(v.faceDescriptor().size()!=128||v.faceDescriptor().stream().anyMatch(x->x==null||!Double.isFinite(x)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Face verification data is invalid.");
        if(s[11]==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Enroll your face from your profile before checking in.");
        try{List<Double> enrolled=json.readValue((String)s[11],json.getTypeFactory().constructCollectionType(List.class,Double.class));double distance=distance(v.faceDescriptor(),enrolled);if(distance>0.45){logEvent(student,session,"FACE_MISMATCH","Euclidean distance exceeded threshold",req);throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Face did not match the enrolled profile.");}}
        catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Could not verify the enrolled face template.");}
        double distance=distance(v.faceDescriptor(),readVector((String)s[11]));
        double meters=distanceMeters(v.latitude(),v.longitude(),(Double)s[5],(Double)s[6]);if(meters>(double)s[7]){logEvent(student,session,"OUTSIDE_GEOFENCE","Location was outside configured radius",req);throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You are outside the classroom attendance area.");}
        try{db.update("INSERT INTO used_qr_nonce(session_id,student_id,nonce) VALUES(?,?,?)",session,student,v.nonce());}catch(DuplicateKeyException e){logEvent(student,session,"QR_REPLAY","QR nonce reused by the same student",req);throw new ResponseStatusException(HttpStatus.CONFLICT,"This QR has already been used on this account.");}
        try{db.update("INSERT INTO attendance_record(id,session_id,student_id,student_name,enrollment_number,department,subject_id,verification_method,status,nonce,latency_ms,similarity_score,ip_address,user_agent) VALUES(?,?,?,?,?,?,?,'BIOMETRIC_QR','PRESENT',?,?,?,?,?)",UUID.randomUUID(),session,student,s[8],s[9],s[10],s[1],v.nonce(),(int)((System.nanoTime()-started)/1_000_000),1.0-distance,req.getRemoteAddr(),req.getHeader("User-Agent"));}
        catch(DuplicateKeyException e){logEvent(student,session,"DUPLICATE_ATTENDANCE","Unique attendance constraint rejected duplicate",req);throw new ResponseStatusException(HttpStatus.CONFLICT,"Attendance is already recorded for this session.");}
        db.update("UPDATE attendance_session SET total_attended=total_attended+1 WHERE id=?",session);
        Map<String,Object> event=Map.of("type","student_verified","sessionId",session,"studentId",student,"studentName",s[8],"enrollmentNumber",s[9]==null?"":s[9],"verifiedAt",Instant.now(),"verificationMethod","BIOMETRIC_QR");SessionSocketHandler.broadcast(session,event);
        return Map.of("success",true,"status","PRESENT","message","Attendance marked successfully.","latencyMs",(System.nanoTime()-started)/1_000_000,"similarityScore",1.0-distance);
    }
    @GetMapping("/history/student") @PreAuthorize("hasRole('STUDENT')") List<Map<String,Object>> history(@AuthenticationPrincipal String who){return db.queryForList("SELECT r.verified_at AS \"verifiedAt\",r.status,r.verification_method AS \"verificationMethod\",r.similarity_score AS \"similarityScore\",r.latency_ms AS \"latencyMs\",s.subject_code AS \"subjectCode\",s.subject_name AS \"subjectName\",s.room_number AS \"roomNumber\" FROM attendance_record r JOIN attendance_session s ON s.id=r.session_id WHERE r.student_id=? ORDER BY r.verified_at DESC",UUID.fromString(who));}
    @GetMapping("/sessions") @PreAuthorize("hasRole('TEACHER')") List<Map<String,Object>> sessions(@AuthenticationPrincipal String who){return db.queryForList("SELECT id,subject_id AS \"subjectId\",subject_code AS \"subjectCode\",subject_name AS \"subjectName\",room_number AS \"roomNumber\",batch,status,started_at AS \"startedAt\",ended_at AS \"endedAt\",total_attended AS \"totalAttended\" FROM attendance_session WHERE teacher_id=? ORDER BY started_at DESC LIMIT 300",UUID.fromString(who));}
    @GetMapping("/analytics/overview") @PreAuthorize("hasRole('TEACHER')") Map<String,Object> analytics(@AuthenticationPrincipal String who){return db.query("SELECT count(DISTINCT s.id) AS sessions,count(r.id) FILTER(WHERE r.status IN ('PRESENT','LATE')) AS present,count(r.id) FILTER(WHERE r.status='LATE') AS late,count(r.id) FILTER(WHERE r.status='EXCUSED') AS excused,coalesce(avg(r.latency_ms),0) AS average_latency FROM attendance_session s LEFT JOIN attendance_record r ON r.session_id=s.id WHERE s.teacher_id=?",rs->{rs.next();return Map.of("sessions",rs.getLong("sessions"),"present",rs.getLong("present"),"late",rs.getLong("late"),"excused",rs.getLong("excused"),"averageLatencyMs",rs.getDouble("average_latency"));},UUID.fromString(who));}
    @GetMapping("/session/{id}/roster") @PreAuthorize("hasRole('TEACHER')") List<Map<String,Object>> roster(@AuthenticationPrincipal String who,@PathVariable String id){UUID ses=uuid(id),teacher=UUID.fromString(who);if(db.queryForObject("SELECT count(*) FROM attendance_session WHERE id=? AND teacher_id=?",Integer.class,ses,teacher)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Session not found.");return db.queryForList("SELECT student_id AS \"studentId\",student_name AS \"studentName\",enrollment_number AS \"enrollmentNumber\",status,verified_at AS \"verifiedAt\",verification_method AS \"verificationMethod\",latency_ms AS \"latencyMs\" FROM attendance_record WHERE session_id=? ORDER BY verified_at",ses);}
    @PostMapping("/override") @PreAuthorize("hasRole('TEACHER')") @Transactional Map<String,Object> override(@AuthenticationPrincipal String who,@Valid @RequestBody Override v,jakarta.servlet.http.HttpServletRequest req){UUID teacher=UUID.fromString(who),session=uuid(v.sessionId()),student=uuid(v.studentId());Object[] s=db.query("SELECT teacher_id,subject_id FROM attendance_session WHERE id=?",rs->rs.next()?new Object[]{rs.getObject(1,UUID.class),rs.getObject(2,UUID.class)}:null,session);if(s==null||!teacher.equals(s[0]))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Session unavailable.");var person=db.queryForMap("SELECT name,enrollment_number,department FROM app_user WHERE id=? AND role='STUDENT'",student);String name=(String)person.get("name");String old=db.query("SELECT status FROM attendance_record WHERE session_id=? AND student_id=?",rs->rs.next()?rs.getString(1):"ABSENT",session,student);db.update("INSERT INTO attendance_record(id,session_id,student_id,student_name,enrollment_number,department,subject_id,verification_method,status,nonce,latency_ms,similarity_score,is_manual_override,override_reason,overridden_by,overridden_at,ip_address,user_agent) VALUES(?,?,?,?,?,?,?,'MANUAL_OVERRIDE',?,?,0,0,true,?,?,now(),?,?) ON CONFLICT(session_id,student_id) DO UPDATE SET status=EXCLUDED.status,verification_method='MANUAL_OVERRIDE',is_manual_override=true,override_reason=EXCLUDED.override_reason,overridden_by=EXCLUDED.overridden_by,overridden_at=now()",UUID.randomUUID(),session,student,name,person.get("enrollment_number"),person.get("department"),s[1],v.status(),"OVERRIDE-"+UUID.randomUUID(),v.reason(),teacher,req.getRemoteAddr(),req.getHeader("User-Agent"));db.update("INSERT INTO audit_log(id,teacher_id,student_id,session_id,old_status,new_status,reason,notes,ip_address,user_agent) VALUES(?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),teacher,student,session,old,v.status(),v.reason(),v.notes(),req.getRemoteAddr(),req.getHeader("User-Agent"));db.update("UPDATE attendance_session SET total_attended=(SELECT count(*) FROM attendance_record WHERE session_id=? AND status<>'ABSENT') WHERE id=?",session,session);SessionSocketHandler.broadcast(session,Map.of("type","attendance_overridden","studentId",student,"studentName",name,"oldStatus",old,"newStatus",v.status(),"reason",v.reason()));return Map.of("success",true,"message","Attendance updated and audit logged.");}
    @GetMapping("/audit-logs") @PreAuthorize("hasRole('TEACHER')") List<Map<String,Object>> audits(@AuthenticationPrincipal String who){return db.queryForList("SELECT a.*,u.name AS student_name FROM audit_log a JOIN app_user u ON u.id=a.student_id JOIN attendance_session s ON s.id=a.session_id WHERE a.teacher_id=? ORDER BY a.created_at DESC LIMIT 500",UUID.fromString(who));}
    @GetMapping("/security-events") @PreAuthorize("hasRole('TEACHER')") List<Map<String,Object>> securityEvents(@AuthenticationPrincipal String who){return db.queryForList("SELECT e.id,e.session_id AS \"sessionId\",e.event_type AS \"eventType\",e.detail,e.ip_address AS \"ipAddress\",e.created_at AS \"createdAt\" FROM security_event e JOIN attendance_session s ON s.id=e.session_id WHERE s.teacher_id=? ORDER BY e.created_at DESC LIMIT 500",UUID.fromString(who));}
    @GetMapping("/reports/audit-logs/csv") @PreAuthorize("hasRole('TEACHER')") org.springframework.http.ResponseEntity<String> auditCsv(@AuthenticationPrincipal String who){var rows=audits(who);StringBuilder out=new StringBuilder("sessionId,studentName,oldStatus,newStatus,reason,createdAt\r\n");for(var r:rows)out.append(csvCell(r.get("session_id"))).append(',').append(csvCell(r.get("student_name"))).append(',').append(csvCell(r.get("old_status"))).append(',').append(csvCell(r.get("new_status"))).append(',').append(csvCell(r.get("reason"))).append(',').append(csvCell(r.get("created_at"))).append("\r\n");return org.springframework.http.ResponseEntity.ok().header("Content-Disposition","attachment; filename=swiftattend-audit.csv").body(out.toString());}
    @GetMapping("/reports/session/{id}/csv") @PreAuthorize("hasRole('TEACHER')") org.springframework.http.ResponseEntity<String> csv(@AuthenticationPrincipal String who,@PathVariable String id){UUID ses=uuid(id);if(db.queryForObject("SELECT count(*) FROM attendance_session WHERE id=? AND teacher_id=?",Integer.class,ses,UUID.fromString(who))==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Session not found.");var rows=roster(who,id);StringBuilder out=new StringBuilder("studentId,studentName,enrollmentNumber,status,verifiedAt,verificationMethod,latencyMs\r\n");for(var r:rows)out.append(r.get("studentId")).append(',').append(csvCell(r.get("studentName"))).append(',').append(csvCell(r.get("enrollmentNumber"))).append(',').append(r.get("status")).append(',').append(r.get("verifiedAt")).append(',').append(r.get("verificationMethod")).append(',').append(r.get("latencyMs")).append("\r\n");return org.springframework.http.ResponseEntity.ok().header("Content-Disposition","attachment; filename=swiftattend-session.csv").body(out.toString());}
    @GetMapping(value="/reports/session/{id}/pdf",produces="application/pdf") @PreAuthorize("hasRole('TEACHER')") org.springframework.http.ResponseEntity<byte[]> pdf(@AuthenticationPrincipal String who,@PathVariable String id){UUID ses=uuid(id);var rows=roster(who,id);try(var doc=new org.apache.pdfbox.pdmodel.PDDocument();var bytes=new java.io.ByteArrayOutputStream()){var page=new org.apache.pdfbox.pdmodel.PDPage(org.apache.pdfbox.pdmodel.common.PDRectangle.A4);doc.addPage(page);try(var stream=new org.apache.pdfbox.pdmodel.PDPageContentStream(doc,page)){stream.beginText();stream.setFont(new org.apache.pdfbox.pdmodel.font.PDType1Font(org.apache.pdfbox.pdmodel.font.Standard14Fonts.FontName.HELVETICA_BOLD),17);stream.newLineAtOffset(48,790);stream.showText("SwiftAttend | Attendance report");stream.setFont(new org.apache.pdfbox.pdmodel.font.PDType1Font(org.apache.pdfbox.pdmodel.font.Standard14Fonts.FontName.HELVETICA),10);stream.newLineAtOffset(0,-22);String label=db.queryForObject("SELECT subject_code || ' - ' || subject_name || ' / ' || room_number FROM attendance_session WHERE id=?",String.class,ses);stream.showText(label);stream.newLineAtOffset(0,-24);for(var r:rows){stream.showText(String.format("%s | %s | %s | %s",String.valueOf(r.get("enrollmentNumber")),safePdf(String.valueOf(r.get("studentName"))),r.get("status"),String.valueOf(r.get("verifiedAt"))));stream.newLineAtOffset(0,-15);}}doc.save(bytes);return org.springframework.http.ResponseEntity.ok().header("Content-Disposition","attachment; filename=swiftattend-session.pdf").body(bytes.toByteArray());}catch(Exception e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Could not generate the report.");}}

    static UUID uuid(String s){try{return UUID.fromString(s);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid identifier.");}}
    static String sign(byte[] secret,String text){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret,"HmacSHA256"));return HexFormat.of().formatHex(m.doFinal(text.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    static double distance(List<Double>a,List<Double>b){if(a.size()!=128||b.size()!=128)return Double.POSITIVE_INFINITY;double sum=0;for(int i=0;i<128;i++){double d=a.get(i)-b.get(i);sum+=d*d;}return Math.sqrt(sum);}
    static TimestampResult timestampStatus(long timestamp,long now,long maxAge,long futureSkew){long delta=now-timestamp;if(delta< -futureSkew)return TimestampResult.FUTURE;if(delta>maxAge)return TimestampResult.EXPIRED;return TimestampResult.VALID;}
    private List<Double> readVector(String jsonString){try{return json.readValue(jsonString,json.getTypeFactory().constructCollectionType(List.class,Double.class));}catch(Exception e){throw new IllegalStateException(e);}}
    static double distanceMeters(double lat1,double lon1,double lat2,double lon2){double r=6371000, dLat=Math.toRadians(lat2-lat1),dLon=Math.toRadians(lon2-lon1);double a=Math.sin(dLat/2)*Math.sin(dLat/2)+Math.cos(Math.toRadians(lat1))*Math.cos(Math.toRadians(lat2))*Math.sin(dLon/2)*Math.sin(dLon/2);return r*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));}
    private static String csvCell(Object o){String s=o==null?"":o.toString();return "\""+s.replace("\"","\"\"")+"\"";}
    private static String safePdf(String s){return s.replaceAll("[^\\x20-\\x7E]","?");}
    private void logEvent(UUID actor,UUID session,String type,String detail,jakarta.servlet.http.HttpServletRequest req){try{securityEvents.record(actor,session,type,detail,req.getRemoteAddr());}catch(Exception ignored){}}
}

